<template><div v-loading="loading"><div class="page-header"><div><h1>社区设置</h1><p>查看当前开源社区配置和已启用能力</p></div></div><ElRow :gutter="18"><ElCol :span="12"><ElCard class="panel-card" shadow="never"><template #header><strong>基本资料</strong></template><ElDescriptions v-if="data" :column="1" border><ElDescriptionsItem label="社区名称">{{data.communityName}}</ElDescriptionsItem><ElDescriptionsItem label="社区编码">{{data.communityCode}}</ElDescriptionsItem><ElDescriptionsItem label="社区 ID">{{data.communityId}}</ElDescriptionsItem></ElDescriptions></ElCard></ElCol><ElCol :span="12"><ElCard class="panel-card" shadow="never"><template #header><strong>部署说明</strong></template><ElAlert title="当前为开源单社区模式" type="success" :closable="false" description="不依赖商业 SaaS 后端，不包含租户开通、套餐、订阅和计费。" show-icon/></ElCard></ElCol></ElRow><ElCard v-if="data" class="panel-card features" shadow="never"><template #header><strong>已启用功能</strong></template><ElTag v-for="(enabled,code) in data.features" :key="code" :type="enabled?'success':'info'" effect="light">{{code}}：{{enabled?'已启用':'未启用'}}</ElTag></ElCard></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{getBootstrap,type Bootstrap}from'@/api/merchant';const loading=ref(false),data=ref<Bootstrap>();onMounted(async()=>{loading.value=true;try{data.value=await getBootstrap()}catch{ElMessage.error('社区配置加载失败')}finally{loading.value=false}})</script>
<style scoped>.features{margin-top:18px}.features .el-tag{margin:0 10px 10px 0}</style>
